import socket

# Prompt the user to enter the IP address of the remote server
remote_server_ip = '10.140.113.123'#input('Enter the IP address of the remote server: ')

# Prompt the user to enter the port number of the remote server
port = 12345 #int(input('Enter the port number of the remote server: '))

# Create a socket object
#client_socket = socket.socket(socket.AF_INET, socket.SOCK_STREAM)
#client_socket.settimeout(10)
# Connect to the server
#client_socket.connect((remote_server_ip, port))
client_socket = None
while True:
    #if client_socket is None:
    #Create a socket object
    client_socket = socket.socket(socket.AF_INET, socket.SOCK_STREAM)
    # Connect to the server
    client_socket.connect((remote_server_ip, port))
    # Get Python code input from the user
    code = input('>>>')
    
    if code in ['quit', 'exit', 'q']:
        break
    # Send the code to the server
    client_socket.sendall(code.encode())

# Close the connection
client_socket.close()
